INSERT INTO releases (version, released_on, title, public_notes, tech_notes) VALUES (
  '2.118.0',
  '2026-10-06',
  'Медиатека: резервная копия разметки в Telegram и сообщение, когда кончается место',
  E'Раз в неделю агент медиатеки складывает в архив всё, чего больше нигде нет: отметки заставки и титров, папки-подборки, избранное, ссылки «где ещё посмотреть», «Продолжить просмотр», обложки, выбранный фон и кадры для карточек. Архив ложится на внешний диск, а копия приходит в Telegram — это и есть хранение вне дома. Внутри лежит ЧТО-ЭТО.txt с описанием и порядком возврата, так что через полгода не придётся вспоминать, что это за файл.\n\nФильмы и так лежат на дисках, а вот разметка жила в одном экземпляре на системном диске мини-сервера — том самом, где кончается место. Это часы ручной и машинной работы: одни отметки заставки по всем сезонам Star Trek размечались звуком несколько заходов.\n\nВ админке, на «Обслуживании», видно, когда копия собиралась, сколько весит и ушла ли она в Telegram, и есть кнопка «Сделать копию сейчас».\n\nЗаодно агент раз в час смотрит на свободное место — своё и каждой библиотеки. Осталось меньше десяти гигабайт — приходит сообщение; напоминание не чаще раза в сутки, но сразу, если место стало кончаться быстро. Когда освободилось — одно сообщение и об этом, чтобы не гадать.',
  E'backup.go в агенте: ZIP из кэша с пропуском того, что соберётся заново (probe.json, photos/, transcoded/, uploads/, APK), восемь последних архивов, недельный срок и ручка POST /api/admin/backup. Ключ подписи ссылок (secret) в архив НЕ кладём: секрету не место в том, что уезжает наружу, а новый агент заведёт свой — перестанут работать только ссылки, открытые в браузере в эту минуту.\n\nbackup_dir по умолчанию равен самому кэшу, то есть тому же диску, от потери которого копия и спасает: на реальной машине его надо задать руками (на res-i3 — внешний диск). Это записано в README и HANDOFF.\n\nОтправка в Telegram идёт через прод, а не напрямую: токен бота живёт только там. Новая ручка POST /api/v1/tv/notify/file — multipart с room, caption и файлом, тот же пропуск по ключу комнаты и тот же счётчик в час, что у текстового уведомления, предел 25 МБ на стороне прода (агент не шлёт крупнее 20 МБ). notify.Bot.SendDocument собирает multipart для sendDocument с увеличенным таймаутом.\n\nПрисмотр за местом дедуплицирует разделы по st_dev — у библиотеки фильмов и кэша он часто один, и предупреждать дважды незачем. Повтор не чаще суток, но сразу, если свободного стало меньше на четверть; возврат выше порога с запасом в 20 % снимает отметку и шлёт сообщение — иначе на границе сообщения мигали бы.\n\nПопутно: safeFileName на Linux не обрезал windows-путь, потому что filepath.Base не считает обратный слэш разделителем — поймано тестом, исправлено приведением слэшей.\n\nПроверено: состав архива (разметка внутри, secret и кэш снаружи), ротация с сохранением чужих файлов в папке, ручка под PIN, память предупреждений о месте, multipart до Telegram на подменённом API и отказ Telegram, который не должен проглатываться.'
);
-- +goose StatementEnd

